			let noDataInRange = i0 > i1; // works for mode 1 only

			closestDist = inf;

			// TODO: extract
			let xDim = scaleX.ori == 0 ? plotWidCss : plotHgtCss;
			let yDim = scaleX.ori == 1 ? plotWidCss : plotHgtCss;

